const todas = [
  { termo: 'estúdio de pilates Goiânia', nicho: 'pilates' },
  { termo: 'CT de luta Goiânia', nicho: 'luta' },
  { termo: 'escola de natação Goiânia', nicho: 'natacao' },
  { termo: 'escola de idiomas Goiânia', nicho: 'idioma' },
  { termo: 'personal trainer Goiânia', nicho: 'personal' },
  { termo: 'escola de ballet Goiânia', nicho: 'ballet' }
];

// 5 nichos por dia x 2 contatos = 10. O nicho que fica de fora e a posicao
// nos resultados do Google mudam a cada dia, pra nao repetir os mesmos lugares.
const dia = Math.floor((Date.now() - 3 * 3600 * 1000) / 86400000);
const pular = dia % todas.length;
const offset = (dia * 2) % 20;

return todas
  .filter((_, i) => i !== pular)
  .map(v => ({ json: { ...v, quantidade: 2, offset } }));

const verticais = $('Mapear verticais').all();
const lugares = [];

$input.all().forEach((item, i) => {
  const v = verticais[i].json;
  const results = item.json.results || [];
  const n = Math.min(v.quantidade, results.length);
  for (let k = 0; k < n; k++) {
    const place = results[(v.offset + k) % results.length];
    lugares.push({
      json: {
        place_id: place.place_id,
        nome: place.name,
        vertical: v.nicho,
        endereco: place.formatted_address || '',
        google_maps_url: `https://www.google.com/maps/place/?q=place_id:${place.place_id}`
      }
    });
  }
});

return lugares;

const lugares = $('Separar lugares').all();

function instagramDe(url) {
  const m = (url || '').match(/instagram\.com\/([A-Za-z0-9_.]+)/i);
  return m ? m[1] : '';
}

return $input.all().map((item, i) => {
  const l = lugares[i].json;
  const r = item.json.result || {};
  const reviews = (r.reviews || [])
    .filter(x => x.text)
    .slice(0, 3)
    .map(x => ({ nota: x.rating, texto: x.text.slice(0, 300) }));

  return {
    json: {
      nome: l.nome,
      place_id: l.place_id,
      vertical: l.vertical,
      telefone: r.formatted_phone_number || '',
      instagram_handle: instagramDe(r.website),
      google_maps_url: r.url || l.google_maps_url,
      status_google: item.json.status,
      dados_google: {
        endereco: l.endereco,
        nota: r.rating || null,
        avaliacoes: r.user_ratings_total || 0,
        site: r.website || '',
        resumo: r.editorial_summary?.overview || '',
        reviews
      }
    }
  };
});
